(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-979":{scenario:{company:"Bình Nguyên Logistics Hub",supervisor:{name:"Quách Thế Vinh",role:{vi:"Giám đốc Rủi ro & Tuân thủ",en:"Chief Risk & Compliance Officer"}},ref_code:"SEC-4417",title:{vi:"Đúng mức sự cố. Đủ người trực. Giữ nguyên chứng cứ.",en:"Right severity. Enough guards. Evidence intact."},brief:{vi:"Đây là tình huống đào tạo. Lúc 02:10 camera ghi nhận một người lạ bám đuôi qua cổng thẻ vào lồng hàng giá trị cao của kho B và lấy đi 2 thùng linh kiện (thiệt hại mô phỏng 380 triệu đồng). Bản nháp báo cáo SEC-4417 xếp sự cố mức SEV-3 và đề xuất 15 bảo vệ cho 5 chốt trực 24/7 sau sự cố. Đối chiếu với ma trận sự cố đã duyệt, sửa mức độ sự cố và số bảo vệ cần bố trí, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. At 02:10 CCTV recorded an unknown person tailgating through the card gate into the high-value cage of warehouse B and removing 2 cartons of components (training loss 380 million VND). Draft report SEC-4417 rates the incident SEV-3 and proposes 15 guards for 5 posts staffed 24/7 after the incident. Compare it with the approved incident matrix, correct the severity and the guard headcount, then write an evidence-based report."},reference_title:{vi:"Ma trận sự cố & định biên an ninh đã duyệt · SEC-4417",en:"Approved incident matrix & security staffing · SEC-4417"},fields:[{id:"INC_SEV",label:{vi:"Mức độ sự cố",en:"Incident severity"},initial:"SEV-3",expected:"SEV-1",choices:["SEV-1","SEV-2","SEV-3"],reference:"Ma trận phân loại sự cố an ninh",hint:{vi:"Đã có xâm nhập vùng hạn chế và mất tài sản thật: ma trận xếp vào mức cao nhất, không phải vi phạm nội quy thông thường.",en:"There was a real intrusion into a restricted zone with actual loss: the matrix puts it at the top level, not a routine policy breach."}},{id:"GUARD_FTE",label:{vi:"Số bảo vệ cần bố trí (người)",en:"Guards required (headcount)"},initial:"15",expected:"18",reference:"Bảng định biên chốt trực",ref_value:{vi:"5 chốt trực 24 giờ x 7 ngày; giờ làm việc bình thường tối đa 48 giờ/người/tuần",en:"5 posts staffed 24 hours x 7 days; normal working time max 48 hours per guard per week"},hint:{vi:"Đừng lấy số chốt nhân 3 ca: mỗi người chỉ làm 48 giờ/tuần, hãy tính tổng giờ trực rồi chia và làm tròn lên.",en:"Do not multiply posts by 3 shifts: each guard works only 48 hours a week, so total the post-hours, divide and round up."}}],sop32:{vi:"Số bảo vệ cần = tổng giờ trực của các chốt trong tuần ÷ 48 giờ/người/tuần, làm tròn lên số nguyên; chưa tính dự phòng nghỉ phép (quy tắc mô phỏng).",en:"Guards required = total weekly post-hours ÷ 48 hours per guard per week, rounded up to a whole number; leave relief not included (training rule)."},context:{label:"SOC / SEC-4417",metrics:[{label:{vi:"Chốt trực 24/7",en:"Posts staffed 24/7"},value:"5"},{label:{vi:"Giờ chuẩn mỗi người/tuần",en:"Standard hours per guard/week"},value:"48 h"},{label:{vi:"Thiệt hại mô phỏng",en:"Training loss"},value:"380,000,000 VND"}]},crisis:{vi:"Đội trưởng nhà thầu bảo vệ nhắn: “Anh ghi SEV-3 giúp em, coi như hao hụt do kiểm đếm. Em sẽ cho xóa đoạn camera đêm qua, cuối tháng có quà cảm ơn. Khách hàng mà biết thì bên em mất hợp đồng.”",en:"The guard contractor's team leader texts: “Please log it as SEV-3, call it a stock count shortfall. I'll have last night's footage deleted and there's a thank-you gift at month end. If the client finds out we lose the contract.”"},options:{safe:{vi:"Giữ mức SEV-1, khóa và sao lưu đoạn camera làm chứng cứ, từ chối quà, báo Giám đốc Rủi ro và khách hàng theo hợp đồng, phối hợp công an điều tra.",en:"Keep SEV-1, lock and back up the footage as evidence, decline the gift, report to the Chief Risk Officer and the client per contract, and support the police investigation."},shortcut:{vi:"Ghi SEV-3 và để nhà thầu xóa đoạn camera cho êm chuyện, tự bù hàng sau.",en:"Log SEV-3, let the contractor delete the footage to keep things quiet and replace the stock later."},wait:{vi:"Chưa xử lý gì, chờ nhà thầu tự điều tra rồi báo lại.",en:"Do nothing for now and wait for the contractor to investigate and report back."}},questions:{vi:["Vì sao sự cố phải xếp SEV-1 chứ không phải SEV-3? Dữ kiện nào từ camera và ma trận chứng minh điều đó?","Bạn tính số bảo vệ cần bố trí thế nào, và xử lý ra sao trước đề nghị xóa camera kèm quà của nhà thầu?"],en:["Why must the incident be rated SEV-1 rather than SEV-3? Which CCTV facts and matrix rules prove it?","How did you calculate the guard headcount, and how do you handle the contractor's offer to delete footage in exchange for a gift?"]},hints:{vi:["Đặt bản nháp cạnh ma trận sự cố và đánh dấu dòng mức độ đang bị hạ thấp.","Tính tổng giờ trực trong tuần của các chốt rồi áp dụng SOP mục 3.2, nhớ làm tròn lên.","Đọc lại SOP mục 4.2: chứng cứ sự cố phải được bảo toàn, mọi đề nghị che giấu phải báo cáo cấp trên."],en:["Place the draft next to the incident matrix and flag the severity line that was downgraded.","Total the weekly post-hours, apply SOP 3.2 and remember to round up.","Re-read SOP 4.2: incident evidence must be preserved and any request to conceal must be escalated."]}},learning:{summary:{vi:"Quản lý an ninh doanh nghiệp xây dựng và vận hành hệ thống bảo vệ con người, tài sản, thông tin và hoạt động kinh doanh: đánh giá rủi ro an ninh, thiết kế phân vùng và kiểm soát ra vào, giám sát camera, định biên bảo vệ, quản lý nhà thầu và điều tra sự cố. Nghề đòi hỏi tư duy rủi ro, hiểu pháp luật lao động và dữ liệu cá nhân, phối hợp tốt với cơ quan công an và giữ liêm chính tuyệt đối khi xử lý chứng cứ.",en:"A corporate security manager builds and runs the protection of people, assets, information and operations: security risk assessment, zoning and access control, CCTV monitoring, guard staffing, contractor management and incident investigation. The role requires risk thinking, knowledge of labour and personal data law, close cooperation with the police and absolute integrity when handling evidence."},responsibilities:{vi:["Đánh giá rủi ro an ninh định kỳ cho từng khu vực, tài sản và quy trình trọng yếu.","Thiết kế phân vùng, kiểm soát ra vào, camera và báo động tương xứng với mức trọng yếu của tài sản.","Lập định biên, lịch trực và giám sát chất lượng nhà thầu bảo vệ theo cam kết dịch vụ (SLA).","Tiếp nhận, phân loại, điều tra sự cố, bảo toàn chứng cứ và phối hợp với cơ quan công an.","Xây dựng kế hoạch ứng phó khẩn cấp, tổ chức diễn tập và đào tạo nhận thức an ninh cho nhân viên."],en:["Run periodic security risk assessments for each zone, critical asset and process.","Design zoning, access control, CCTV and alarms in proportion to asset criticality.","Plan headcount and rosters and monitor guard contractor performance against the SLA.","Receive, classify and investigate incidents, preserve evidence and cooperate with the police.","Build emergency response plans, run drills and deliver security awareness training to staff."]},competencies:[{name:{vi:"Đánh giá rủi ro an ninh",en:"Security risk assessment"},desc:{vi:"Nhận diện mối đe dọa, lỗ hổng, hậu quả và xếp hạng rủi ro bằng ma trận khả năng x tác động.",en:"Identify threats, vulnerabilities and consequences and rank risks with a likelihood x impact matrix."}},{name:{vi:"Thiết kế kiểm soát vật lý",en:"Physical control design"},desc:{vi:"Bố trí lớp bảo vệ nhiều tầng: rào, cổng, thẻ, camera, báo động và tuần tra, chống bám đuôi.",en:"Layer defences: fences, gates, cards, CCTV, alarms and patrols, including anti-tailgating measures."}},{name:{vi:"Điều tra & quản lý chứng cứ",en:"Investigation & evidence handling"},desc:{vi:"Thu thập, niêm phong, lưu giữ chứng cứ theo chuỗi lưu giữ để có giá trị khi chuyển cơ quan chức năng.",en:"Collect, seal and store evidence under chain of custody so it stays valid when handed to authorities."}},{name:{vi:"Quản lý nhà thầu & định biên",en:"Contractor & staffing management"},desc:{vi:"Tính định biên đúng giới hạn giờ làm, giám sát SLA, xử phạt và cải tiến dịch vụ bảo vệ thuê ngoài.",en:"Size headcount within working time limits, monitor SLAs, apply penalties and improve outsourced guarding."}},{name:{vi:"Liêm chính & tuân thủ",en:"Integrity & compliance"},desc:{vi:"Từ chối che giấu sự cố, không nhận quà từ nhà thầu, tôn trọng quyền riêng tư và dữ liệu cá nhân.",en:"Refuse to conceal incidents, accept no gifts from contractors and respect privacy and personal data."}}],knowledge:{vi:["ISO 31000 về quản lý rủi ro: nhận diện, phân tích, đánh giá và xử lý rủi ro.","ISO 28000 về hệ thống quản lý an ninh chuỗi cung ứng và ISO 22301 về quản lý kinh doanh liên tục.","Bộ luật Lao động 2019: giờ làm việc bình thường không quá 8 giờ/ngày và 48 giờ/tuần, có giới hạn làm thêm giờ.","Pháp luật hiện hành về bảo vệ dữ liệu cá nhân, áp dụng cho hình ảnh camera và nhật ký ra vào.","Quy định về điều kiện an ninh, trật tự đối với doanh nghiệp kinh doanh dịch vụ bảo vệ khi thuê ngoài.","Phương pháp phòng ngừa tội phạm qua thiết kế môi trường (CPTED) và nguyên tắc chuỗi lưu giữ chứng cứ."],en:["ISO 31000 on risk management: identifying, analysing, evaluating and treating risk.","ISO 28000 on supply chain security management systems and ISO 22301 on business continuity management.","Vietnam Labour Code 2019: normal working time up to 8 hours a day and 48 hours a week, with overtime limits.","Current personal data protection law, which applies to CCTV images and access logs.","Regulations on security and order conditions for licensed guarding service providers.","Crime Prevention Through Environmental Design (CPTED) and chain of custody principles."]},tools:["Hệ thống quản lý video (VMS)","Hệ thống kiểm soát ra vào (ACS)","Phần mềm quản lý sự cố an ninh","Sổ đăng ký & ma trận rủi ro","Ứng dụng tuần tra điện tử và bộ đàm","Bảng tính định biên"],kpis:{vi:["Thời gian từ lúc báo động đến khi có người tại hiện trường.","Tỷ lệ sự cố được phân loại và báo cáo đúng hạn theo ma trận.","Tỷ lệ chốt trực đủ quân số, tuần tra đúng tuyến và đúng giờ.","Tổn thất do mất cắp so với giá trị hàng lưu kho."],en:["Time from alarm to a guard on scene.","Share of incidents classified and reported on time per the matrix.","Share of posts fully staffed and patrols completed on route and on time.","Theft losses as a share of stored inventory value."]},day:[{time:"07:30",vi:"Nhận bàn giao ca đêm, xem nhật ký sự cố và cảnh báo từ trung tâm giám sát.",en:"Take the night shift handover, review the incident log and monitoring alerts."},{time:"09:00",vi:"Họp nhanh với nhà thầu bảo vệ, kiểm tra quân số và chất lượng tuần tra.",en:"Hold a stand-up with the guard contractor and check headcount and patrol quality."},{time:"11:00",vi:"Rà soát quyền thẻ vào vùng hạn chế, thu hồi thẻ của người đã nghỉ việc.",en:"Review restricted zone card rights and revoke cards of leavers."},{time:"14:00",vi:"Điều tra sự cố, trích xuất và niêm phong dữ liệu camera theo chuỗi lưu giữ.",en:"Investigate an incident, export and seal CCTV data under chain of custody."},{time:"16:30",vi:"Cập nhật sổ đăng ký rủi ro và báo cáo lãnh đạo biện pháp khắc phục.",en:"Update the risk register and report corrective actions to management."}],mistakes:{vi:["Hạ mức độ sự cố để tránh ảnh hưởng hợp đồng hoặc KPI, làm mất cơ hội xử lý nguyên nhân gốc.","Định biên bằng số chốt nhân số ca, khiến bảo vệ làm vượt giờ và chốt bị bỏ trống.","Để dữ liệu camera bị ghi đè hoặc chỉnh sửa trước khi trích xuất, làm mất giá trị chứng cứ."],en:["Downgrading incidents to protect a contract or KPI, losing the chance to fix the root cause.","Sizing headcount as posts times shifts, which causes excessive hours and empty posts.","Letting CCTV data be overwritten or edited before export, destroying its value as evidence."]},career:[{vi:"Nhân viên giám sát an ninh",en:"Security monitoring officer"},{vi:"Trưởng ca trung tâm giám sát an ninh",en:"Security operations shift lead"},{vi:"Quản lý an ninh doanh nghiệp",en:"Corporate security manager"},{vi:"Giám đốc an ninh & rủi ro (CSO)",en:"Chief Security Officer (CSO)"}],glossary:[{term:"Tailgating",vi:"Hành vi bám sát người có thẻ để đi qua cửa kiểm soát mà không xác thực.",en:"Following an authorised person through a controlled door without authenticating."},{term:"Chain of custody",vi:"Hồ sơ ghi nhận ai thu giữ, chuyển giao, lưu trữ chứng cứ và vào thời điểm nào.",en:"Record of who seized, transferred and stored evidence, and when."},{term:"SOC",vi:"Trung tâm điều hành an ninh, nơi giám sát camera, báo động và điều phối ứng phó.",en:"Security operations centre that monitors CCTV and alarms and coordinates response."},{term:"CPTED",vi:"Phòng ngừa tội phạm bằng thiết kế không gian: chiếu sáng, tầm nhìn, ranh giới, kiểm soát lối đi.",en:"Crime prevention through design of space: lighting, sightlines, boundaries and access control."},{term:"SLA",vi:"Cam kết mức dịch vụ giữa doanh nghiệp và nhà thầu, kèm chỉ số đo và chế tài.",en:"Service level agreement between the company and a contractor, with metrics and penalties."}],quiz:[{q:{vi:"Kho có 4 chốt trực 24/7, mỗi bảo vệ làm 48 giờ/tuần. Cần tối thiểu bao nhiêu người (chưa tính dự phòng)?",en:"A warehouse has 4 posts staffed 24/7 and each guard works 48 hours a week. What is the minimum headcount (excluding relief)?"},options:{vi:["12 người","14 người","16 người","8 người"],en:["12 guards","14 guards","16 guards","8 guards"]},answer:1,explain:{vi:"4 x 168 = 672 giờ trực/tuần; 672 ÷ 48 = 14 người.",en:"4 x 168 = 672 post-hours per week; 672 ÷ 48 = 14 guards."}},{q:{vi:"Kẻ gian bám đuôi qua cửa thẻ là lỗ hổng của lớp kiểm soát nào?",en:"Tailgating through a card door exposes a weakness in which control layer?"},options:{vi:["Kiểm soát an ninh mạng","Kiểm soát kế toán","Kiểm soát nhân sự tuyển dụng","Kiểm soát ra vào vật lý"],en:["Cyber security control","Accounting control","Recruitment control","Physical access control"]},answer:3,explain:{vi:"Bám đuôi vượt qua cửa kiểm soát ra vào; cần cửa xoay một người, cảnh báo cửa mở lâu và đào tạo nhân viên.",en:"Tailgating defeats access control; use single-person turnstiles, door-held alarms and staff training."}},{q:{vi:"Nhà thầu đề nghị xóa camera để che sự cố và hứa có quà. Bạn làm gì?",en:"A contractor offers a gift if you delete footage to hide an incident. What do you do?"},options:{vi:["Từ chối, bảo toàn dữ liệu và báo cáo lãnh đạo, khách hàng","Đồng ý vì thiệt hại nhỏ","Xóa một phần đoạn camera","Im lặng và chờ nhà thầu tự xử lý"],en:["Refuse, preserve the data and report to management and the client","Agree because the loss is small","Delete part of the footage","Stay silent and let the contractor handle it"]},answer:0,explain:{vi:"Che giấu sự cố và hủy chứng cứ là vi phạm nghiêm trọng; phải giữ chứng cứ và báo cáo người có thẩm quyền.",en:"Concealing incidents and destroying evidence is a serious violation; preserve evidence and report to those in authority."}},{q:{vi:"Nguyên tắc chuỗi lưu giữ chứng cứ yêu cầu điều gì?",en:"What does the chain of custody principle require?"},options:{vi:["Chỉ cần lưu bản sao trên điện thoại","Cho mọi người xem để xác minh","Ghi nhận đầy đủ người, thời điểm thu giữ, chuyển giao và lưu trữ","Chỉnh sửa video cho rõ hơn rồi lưu"],en:["Keep a copy on a phone only","Let everyone view it to verify","Record who seized, transferred and stored it and when","Enhance the video before saving it"]},answer:2,explain:{vi:"Chứng cứ chỉ có giá trị khi chứng minh được không bị thay đổi qua từng lần chuyển giao.",en:"Evidence is only valid if it can be shown to be unchanged through every transfer."}}],tools_en:["Video management system (VMS)","Access control system (ACS)","Security incident management software","Risk register & risk matrix","Electronic guard tour app and two-way radios","Staffing spreadsheet"]}}})})(window.KKR);
